import os
import json
from collections import Counter, defaultdict

base = '/home/USER/runs/paper/qwen-h0-card-u2/frozen/seen-reference/play/users/u022/system/state'
session_dir = os.path.join(base, 'session-artifacts')

# Gather all semantic edges with full context
all_entries = []
for root, dirs, files in os.walk(session_dir):
    for f in files:
        if f.endswith('semantic-edges.jsonl'):
            full = os.path.join(root, f)
            with open(full) as fp:
                for line in fp:
                    try:
                        data = json.loads(line)
                        all_entries.append(data)
                    except:
                        pass

# Build a map by request_id
request_map = defaultdict(list)
for e in all_entries:
    if 'request_id' in e:
        rid = e['request_id']
        request_map[rid].append(e)

print(f"Total unique requests: {len(request_map)}")
print()

# Analyze requests by session
sessions = {}
for rid, events in request_map.items():
    for ev in events:
        if 'session_id' in ev:
            sid = ev['session_id']
            if sid not in sessions:
                sessions[sid] = {'started': [], 'finished': []}
            sess_ev = ev.copy()
            del sess_ev['request_id']  # Remove duplicate key
            if ev.get('type') == 'request_started':
                sessions[sid]['started'].append(sess_ev)
            elif ev.get('type') == 'request_finished':
                sessions[sid]['finished'].append(sess_ev)

print("Sessions analysis:")
for sid, sdata in sorted(sessions.items()):
    started = len(sdata['started'])
    finished = len(sdata['finished'])
    print(f"\n  {sid}:")
    print(f"    Started: {started}, Finished: {finished}")
    print(f"    Unfinished: {started - finished}")

